/*
 * libripcord - AES-128-GMAC (NIST SP 800-38D), the authentication-only half of GCM.
 *
 * The counterpart of Ripcord.Core.Net.Crypto.AesGcmCore.Mac (the platform AesGcm type refuses
 * non-96-bit nonces, and the Halyard stream MAC's nonce is a full 16 bytes, so that project implements
 * GCM from the specification too), with a byte-indexed table multiply in place of its bit-serial
 * reference path. Checked against it with cross-language vectors
 * (tests/vectors/stream-crypto.kat's `gmac` lines, generated by `dotnet run --project
 * tools/Ripcord.ProtocolLab -- vectors` via `AesGcmCore.Mac` directly) rather than transcribed NIST test
 * vectors.
 *
 * ONLY GMAC, NOT FULL GCM ENCRYPT/DECRYPT: `HalyardPacketCrypto` computes the tag via `AesGcmCore.Mac`
 * (AAD-only, empty message) and encrypts the payload separately with a little-endian-counter AES-CTR
 * (rc_aes128_ctr(..., little_endian_counter=1) in rc_modes.c). So this file implements GHASH, the
 * GHASH-based J0 derivation for a non-96-bit IV, and the single-block tag, and no GCTR ciphertext path.
 *
 * ONLY THE NON-96-BIT IV PATH: this protocol's IV is always 16 bytes, so only the GHASH-based J0
 * derivation is implemented. A 12-byte IV here would NOT match the shortcut real GCM defines for that
 * length (a deliberate scope decision - see rc_gmac_with_key()'s doc comment).
 */
#ifndef RC_GCM_H
#define RC_GCM_H

#include <stddef.h>
#include <stdint.h>

#include "rc_crypto.h"

/*
 * A GMAC key with its GHASH multiplication tables built.
 *
 * WHY A PREPARED KEY. With a bit-serial GF(2^128) multiply (~69 multiplies per packet), a GMAC over a
 * ~1,100-byte packet measured **1,264 us** on hardware, about 22% of one ARM11 core across a real
 * stream. A byte-indexed table is one lookup and two XORs per input byte, about 5x fewer operations,
 * but the tables cost ~4.6 KB to build, so they are built once per key: this protocol rotates its GMAC
 * key roughly every 650 packets (45,000 keystream-offset units).
 *
 * DO NOT put one on the stack in the 3DS build - it is over the 8 KB frame limit the build enforces
 * (see takion_reliable_channel.h for what an oversized local does on this hardware).
 *
 * The accumulator is four uint32 words and the table is stored pre-packed as words (four word loads per
 * lookup). A `uint8_t[16]` accumulator shifted a byte at a time stalls the PS3's in-order PPE on
 * store-to-load forwarding: the packet cipher and its GMAC together measured 837 us per ~1,400-byte
 * packet. See rc_aes.c's header for the same fix applied to the block cipher.
 */
typedef struct {
    rc_aes128 aes;
    uint8_t h[16];
    uint32_t table[256][4];   /* table[b] = b * H, big-endian words, with b's MSB as the x^0 coefficient */
    uint16_t reduce[256];     /* the reduction produced by shifting byte 15 out, bytes 0..1 only */
    uint8_t key[16];
    int ready;
} rc_gmac_key;

/* Derives H from `key` and builds the tables. Cheap enough to call whenever the key rotates, and far too
 * expensive to call per packet. */
void rc_gmac_key_init(rc_gmac_key *gk, const uint8_t key[16]);

/* 1 if `gk` is already prepared for exactly this key, so a caller can skip a rebuild. */
int rc_gmac_key_matches(const rc_gmac_key *gk, const uint8_t key[16]);

/*
 * Computes the 16-byte GMAC tag over `aad` under a prepared key and `iv` (empty message - this protocol
 * never uses GCM's own encrypt path, see the file header). `iv_len` may be any length except 12 - a
 * 12-byte IV needs GCM's other J0 shortcut, not implemented here since this protocol's IV is always 16
 * bytes. Callers needing the protocol's 4-byte truncated tag take the first 4 bytes of `tag`.
 */
void rc_gmac_with_key(const rc_gmac_key *gk, const uint8_t *iv, size_t iv_len,
                      const uint8_t *aad, size_t aad_len, uint8_t tag[16]);

#endif /* RC_GCM_H */
